        s_w = (TW - 1) * s + (kW - 1) * d + 1
        smem_bytes = (icg * s_d * s_h * s_w + icg * kD * kH * kW) * 4
        d_tiles = (d_out + TD - 1) // TD
        grid = ((w_out + TW - 1) // TW, (h_out + TH - 1) // TH, N * OC * d_tiles)
        module.launch(
            "conv3d_kernel",
            grid=grid,
            block=(256, 1, 1),
            arguments=[
                x, weight, out, bias_arg,
                i32(total), i32(OC), i32(IC),
                i32(d_out), i32(h_out), i32(w_out),
                i32(ID), i32(IH), i32(IW),
